var entretenimento = document.getElementById('coluna-entretenimento');
if (entretenimento && entretenimento.parentNode === element) {
  element.insertBefore(entretenimento, element.firstChild);
}

if (!element._moved) {
  element._moved = true;
  var columnSection = document.querySelector('.area-colunas');
  if (columnSection && element.parentNode) {
    element.parentNode.insertBefore(element, columnSection);
  }
}
